//
//  ViewController.swift — repo-owned, installed by scripts/package.sh
//
//  The container app is native SwiftUI, built for iPhone first and shared with
//  iPad and Mac. It replaces the converter's WKWebView page, which rendered a
//  web page pretending to be an app: no Dynamic Type, no native controls, and
//  on iOS its only button was unwired.
//
//  Everything lives in this one file on purpose. The Xcode project is
//  regenerated by the converter, which only knows about ViewController.swift;
//  a second Swift file would need pbxproj surgery on every regeneration.
//
//  The storyboards still instantiate this controller and connect a `webView`
//  outlet. The outlet stays declared so that connection does not crash; the
//  web view itself is removed and a SwiftUI hosting view takes its place.
//

import Combine
import SwiftUI
import WebKit

#if os(iOS)
import UIKit
typealias PlatformViewController = UIViewController
#elseif os(macOS)
import Cocoa
import SafariServices
typealias PlatformViewController = NSViewController
#endif

let extensionBundleIdentifier = "com.costum.youtube.Extension"

class ViewController: PlatformViewController {

    @IBOutlet var webView: WKWebView!

    override func viewDidLoad() {
        super.viewDidLoad()
        webView?.removeFromSuperview()

#if os(iOS)
        let host = UIHostingController(rootView: SetupView())
        addChild(host)
        host.view.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(host.view)
        NSLayoutConstraint.activate([
            host.view.topAnchor.constraint(equalTo: view.topAnchor),
            host.view.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            host.view.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            host.view.trailingAnchor.constraint(equalTo: view.trailingAnchor),
        ])
        host.didMove(toParent: self)
#elseif os(macOS)
        let host = NSHostingView(rootView: SetupView())
        host.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(host)
        NSLayoutConstraint.activate([
            host.topAnchor.constraint(equalTo: view.topAnchor),
            host.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            host.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            host.trailingAnchor.constraint(equalTo: view.trailingAnchor),
        ])
        // The storyboard window is a fixed 425×325, sized for the one-line
        // placeholder. Size it before it appears: growing it afterwards
        // leaves the list scrolled to the bottom.
        view.setFrameSize(NSSize(width: 480, height: 660))
#endif
    }

#if os(macOS)
    override func viewWillAppear() {
        super.viewWillAppear()
        guard let window = view.window else { return }
        window.styleMask.insert([.resizable, .miniaturizable])
        window.contentMinSize = NSSize(width: 420, height: 520)
        window.setContentSize(NSSize(width: 480, height: 660))
        window.center()
    }
#endif
}

// MARK: - Model

/// What the app can know about the extension. iOS offers no API to read a
/// Safari extension's state, so the phone never claims to know it; only the
/// Mac reports one.
final class ExtensionStatus: ObservableObject {
    enum State: Equatable {
        case checking, on, off
        /// Safari answered with an error, which is what an unsigned or
        /// unregistered build gets. That is not the same as "off".
        case unknown
    }

    @Published var state: State = .checking
    @Published var error: String?
    /// iOS: when the extension last told the native handler it was running on
    /// a YouTube page (ExtensionPresence in CloudSync.swift). nil until then.
    @Published var lastSeen: Date?

    func refresh() {
#if os(iOS)
        lastSeen = UserDefaults(suiteName: "group.com.costum.youtube")?.object(forKey: "costum.lastSeen") as? Date
#endif
#if os(macOS)
        SFSafariExtensionManager.getStateOfSafariExtension(withIdentifier: extensionBundleIdentifier) { state, _ in
            DispatchQueue.main.async {
                guard let state else { self.state = .unknown; return }
                self.state = state.isEnabled ? .on : .off
            }
        }
#endif
    }

    /// iOS: Settings. Private "App-prefs:" deep links into Safari's page get
    /// an app rejected, so the public URL is the only App Store-safe route,
    /// and the copy beside the button names the rest of the path.
    /// macOS: Safari's own extension settings, opened on this extension.
    func openSettings() {
#if os(iOS)
        guard let url = URL(string: UIApplication.openSettingsURLString) else { return }
        UIApplication.shared.open(url)
#elseif os(macOS)
        // Swallowing the error here means a click that does nothing and says
        // nothing — which is what Safari returns when the app is not signed
        // with a real identity. Show it instead. On success the app stays
        // open: it re-reads the state when the user comes back to it.
        SFSafariApplication.showPreferencesForExtension(withIdentifier: extensionBundleIdentifier) { error in
            DispatchQueue.main.async {
                if let error { self.error = error.localizedDescription }
            }
        }
#endif
    }

    /// Opens YouTube in Safari specifically. A plain https link would open the
    /// YouTube app through its universal link, or another default browser —
    /// both places the extension does not run.
    func openYouTube() {
#if os(iOS)
        let safari = URL(string: "x-safari-https://m.youtube.com")!
        let fallback = URL(string: "https://m.youtube.com")!
        UIApplication.shared.open(safari) { opened in
            if !opened { UIApplication.shared.open(fallback) }
        }
#elseif os(macOS)
        let url = URL(string: "https://www.youtube.com")!
        if let safari = NSWorkspace.shared.urlForApplication(withBundleIdentifier: "com.apple.Safari") {
            NSWorkspace.shared.open([url], withApplicationAt: safari, configuration: NSWorkspace.OpenConfiguration())
        } else {
            NSWorkspace.shared.open(url)
        }
#endif
    }
}

#if os(iOS)
private let didBecomeActive = UIApplication.didBecomeActiveNotification
#elseif os(macOS)
private let didBecomeActive = NSApplication.didBecomeActiveNotification
#endif

// MARK: - Views

struct SetupView: View {
    @StateObject private var status = ExtensionStatus()

    var body: some View {
        GeometryReader { proxy in
            Form {
                Section {
                    Hero()
                }
                .listRowBackground(Color.clear)

                turnOn

                Section("What you can change") {
                    // Tints match the extension's own surface tiles, so a
                    // colour learned here means the same thing on YouTube.
                    Feature(symbol: "gauge.with.dots.needle.67percent", tint: .blue,
                            title: "Speed, sound and picture",
                            detail: "Set a default speed, boost quiet videos, pick quality and keep it.")
                    Feature(symbol: "eye.slash.fill", tint: .red,
                            title: "Hide the clutter",
                            detail: "Shorts, comments, recommendations, end cards — switch off what distracts you.")
                    Feature(symbol: "forward.end.fill", tint: .green,
                            title: "Skip sponsor segments",
                            detail: "Optional, through the community-run SponsorBlock. Off until you turn it on.")
                    Feature(symbol: "sparkles", tint: .purple,
                            title: "Summaries",
                            detail: "Summarize a video with your own Claude API key. No subscription.")
                    Feature(symbol: "bookmark.fill", tint: .indigo,
                            title: "Bookmarks",
                            detail: "Mark moments in a video and jump back to them later.")
                }

                Section("Private by design") {
                    Feature(symbol: "icloud.fill", tint: .teal,
                            title: "Synced through your iCloud",
                            detail: "Settings follow you across iPhone, iPad and Mac. No account, no server in between.")
                    Feature(symbol: "hand.raised.fill", tint: .gray,
                            title: "Nothing to sign up for",
                            detail: "One purchase unlocks everything, on every device.")
                }
            }
            .formStyle(.grouped)
            .modifier(ReadableColumn(width: proxy.size.width))
        }
        .onAppear { status.refresh() }
        .onReceive(NotificationCenter.default.publisher(for: didBecomeActive)) { _ in
            status.refresh()
        }
        .alert("Safari couldn’t open its settings",
               isPresented: Binding(get: { status.error != nil }, set: { if !$0 { status.error = nil } })) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("\(status.error ?? "")\n\nIn Safari, choose Safari › Settings › Extensions and turn on Costum for YouTube.")
        }
    }

#if os(iOS)
    /// The steps come before the button because the button leaves the app:
    /// once Safari is in front, these words are no longer on screen. So each
    /// step is one short action, in the order Safari presents them.
    ///
    /// iPhone and iPad Safari put extensions in different places. On iPhone
    /// they are in the Page Menu; on iPad the Page Menu has no Manage
    /// Extensions at all, and there is an Extensions button of its own in the
    /// address bar. Safari never asks for the site on its own either: the
    /// extension shows a warning in that same menu until you tap it.
    @ViewBuilder private var turnOn: some View {
        Section {
            PresenceRow(lastSeen: status.lastSeen)
        }

        Section {
            if UIDevice.current.userInterfaceIdiom == .pad {
                Step(number: 1, text: "In Safari, tap the **Extensions** button in the address bar.")
                Step(number: 2, text: "Turn on **Costum for YouTube**.")
                Step(number: 3, text: "Tap **Extensions** again, tap **Costum for YouTube**, and allow it on **youtube.com**.")
            } else {
                Step(number: 1, text: "In Safari, tap the **Page Menu** button in the address bar.")
                Step(number: 2, text: "Tap **Manage Extensions** and turn on **Costum for YouTube**.")
                Step(number: 3, text: "Open the menu again, tap **Costum for YouTube**, and allow it on **youtube.com**.")
            }
            PrimaryButton(title: "Open YouTube in Safari", symbol: "safari", action: status.openYouTube)
                .padding(.vertical, 6)
        } header: {
            Text("Turn it on in Safari")
        } footer: {
            Text("Costum works in Safari, not in the YouTube app. Once it’s on, a round button appears in the corner of every YouTube page. Tap it for all the controls.")
        }

        Section {
            Button(action: status.openSettings) {
                HStack {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Use Settings instead")
                        // Color.secondary, not .secondary: inside a Button
                        // the hierarchical style resolves against the tint.
                        Text("Apps › Safari › Extensions")
                            .font(.subheadline)
                            .foregroundStyle(Color.secondary)
                    }
                    Spacer(minLength: 8)
                    Image(systemName: "arrow.up.forward.app")
                        .foregroundStyle(Color.secondary)
                        .accessibilityHidden(true)
                }
                .contentShape(Rectangle())
            }
            .accessibilityHint("Opens Settings. Go to Apps, Safari, Extensions.")
        }
    }
#elseif os(macOS)
    @ViewBuilder private var turnOn: some View {
        Section {
            LabeledContent("Safari extension") {
                StatusBadge(state: status.state)
            }
            // The default (Return) button is whichever step comes next.
            HStack {
                Spacer()
                if status.state == .on {
                    Button("Safari Settings…", action: status.openSettings)
                    Button("Open YouTube in Safari", action: status.openYouTube)
                        .keyboardShortcut(.defaultAction)
                } else {
                    Button("Open YouTube", action: status.openYouTube)
                    Button("Open Safari Settings…", action: status.openSettings)
                        .keyboardShortcut(.defaultAction)
                }
            }
        } header: {
            Text("Turn it on")
        } footer: {
            Text(status.state == .on
                 ? "A round button appears in the corner of every YouTube page. Click it for all the controls."
                 : "Safari Settings opens on Extensions. Tick Costum for YouTube, then allow it on youtube.com.")
        }
    }
#endif
}

/// A settings-width column on wide windows. Without it an iPad draws the
/// phone layout stretched edge to edge: 620-point buttons and captions
/// running a whole screen wide. Narrow widths keep the system's own margins.
private struct ReadableColumn: ViewModifier {
    let width: CGFloat
    private let column: CGFloat = 600

    func body(content: Content) -> some View {
        if width > column + 120 {
            content.contentMargins(.horizontal, (width - column) / 2, for: .scrollContent)
        } else {
            content
        }
    }
}

private struct Hero: View {
    @ScaledMetric(relativeTo: .title) private var mark: CGFloat = 88

    var body: some View {
        VStack(spacing: 12) {
            Image("LargeIcon")
                .resizable()
                .scaledToFit()
                .frame(width: min(mark, 128), height: min(mark, 128))
                .clipShape(RoundedRectangle(cornerRadius: min(mark, 128) * 0.225, style: .continuous))
                .shadow(color: .black.opacity(0.15), radius: 10, y: 4)
                .accessibilityHidden(true)
            Text("Costum for YouTube")
                .font(.title2.bold())
                .accessibilityAddTraits(.isHeader)
            Text("One purchase. Every feature. No subscription.")
                .font(.subheadline)
                .foregroundStyle(.secondary)
        }
        .multilineTextAlignment(.center)
        .frame(maxWidth: .infinity)
        .padding(.vertical, 8)
    }
}

/// Stacks the icon above the text at accessibility sizes, where a scaled
/// icon beside the text would leave a column a few words wide.
private struct RowLayout<Icon: View, Content: View>: View {
    @Environment(\.dynamicTypeSize) private var typeSize
    let alignment: VerticalAlignment
    @ViewBuilder let icon: Icon
    @ViewBuilder let content: Content

    var body: some View {
        let layout = typeSize.isAccessibilitySize
            ? AnyLayout(VStackLayout(alignment: .leading, spacing: 8))
            : AnyLayout(HStackLayout(alignment: alignment, spacing: 14))
        layout {
            icon
            content
        }
    }
}

private struct Step: View {
    let number: Int
    let text: LocalizedStringKey
    @ScaledMetric(relativeTo: .body) private var size: CGFloat = 26

    var body: some View {
        // First-baseline alignment puts the digit on the same baseline as the
        // step's first line, at any text size, with no hand-tuned offset.
        RowLayout(alignment: .firstTextBaseline) {
            Text("\(number)")
                .font(.subheadline.weight(.semibold).monospacedDigit())
                .foregroundStyle(.white)
                .frame(width: size, height: size)
                .background(Circle().fill(accentFill))
        } content: {
            Text(text)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(.vertical, 2)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(Text("Step \(number): ") + Text(text))
    }
}

/// DESIGN.md's accent-fill: the blue that carries white text at 4.5:1,
/// where system blue manages 4.0:1.
private let accentFill = Color(red: 10 / 255, green: 111 / 255, blue: 219 / 255)

private struct Feature: View {
    let symbol: String
    let tint: Color
    let title: String
    let detail: String
    @ScaledMetric(relativeTo: .body) private var tile: CGFloat = 30

    var body: some View {
        RowLayout(alignment: .top) {
            Image(systemName: symbol)
                .font(.system(size: tile * 0.5, weight: .semibold))
                .foregroundStyle(.white)
                .frame(width: tile, height: tile)
                .background(RoundedRectangle(cornerRadius: tile * 0.26, style: .continuous).fill(tint))
                .accessibilityHidden(true)
        } content: {
            VStack(alignment: .leading, spacing: 2) {
                Text(title).font(.body.weight(.medium))
                Text(detail)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(.vertical, 2)
        .accessibilityElement(children: .combine)
    }
}

#if os(iOS)
/// The one thing iOS will not tell an app: is my extension working? The
/// extension says so itself each time it runs on YouTube.
private struct PresenceRow: View {
    let lastSeen: Date?

    var body: some View {
        if let lastSeen {
            Label {
                VStack(alignment: .leading, spacing: 2) {
                    Text("Costum is working")
                    Text("Last active on YouTube \(lastSeen, format: .relative(presentation: .named))")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            } icon: {
                Image(systemName: "checkmark.circle.fill").foregroundStyle(.green)
            }
            .accessibilityElement(children: .combine)
        } else {
            Label {
                VStack(alignment: .leading, spacing: 2) {
                    Text("Not seen on YouTube yet")
                    Text("Follow the steps below, then open any YouTube page.")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            } icon: {
                Image(systemName: "circle.dashed").foregroundStyle(.secondary)
            }
            .accessibilityElement(children: .combine)
        }
    }
}
#endif

#if os(macOS)
private struct StatusBadge: View {
    let state: ExtensionStatus.State

    var body: some View {
        switch state {
        case .checking:
            HStack(spacing: 6) {
                ProgressView().controlSize(.small)
                Text("Checking…").foregroundStyle(.secondary)
            }
        case .on:
            Label("On", systemImage: "checkmark.circle.fill")
                .foregroundStyle(.green)
        case .off:
            Label("Off", systemImage: "circle.dashed")
                .foregroundStyle(.secondary)
        case .unknown:
            Label("Couldn’t check", systemImage: "questionmark.circle")
                .foregroundStyle(.secondary)
                .help("Safari didn’t report whether the extension is on. Open Safari Settings to see.")
        }
    }
}
#endif

#if os(iOS)
/// Liquid Glass where the OS has it, the standard prominent style before.
/// Not a Label: inside a Form row a Label's icon takes the accent tint,
/// which is invisible on an accent-filled button.
private struct PrimaryButton: View {
    let title: String
    let symbol: String
    let action: () -> Void

    var body: some View {
        let button = Button(action: action) {
            HStack(spacing: 8) {
                Image(systemName: symbol)
                Text(title)
            }
            .font(.body.weight(.semibold))
            .frame(maxWidth: .infinity)
            .padding(.vertical, 4)
        }
        .controlSize(.large)

        if #available(iOS 26, *) {
            button.buttonStyle(.glassProminent)
        } else {
            button.buttonStyle(.borderedProminent)
        }
    }
}
#endif
